/// Resolve an asset's class without changing its routing category. Explicit local overrides win;
/// otherwise preserve the provider's flat taxonomy, interpreting the legacy routing labels only
/// where necessary. Unknown labels remain unknown.
pub fn classify(external_id: &str, category: Option<&str>, instrument_type: Option<&str>) -> Option<AssetClass> {
    if let Some(row) = CATEGORY_OVERRIDES.iter().find(|row| row.external_id == external_id) {
        return Some(row.class);
    }
    if instrument_type == Some("tokenized") { return Some(AssetClass::Rwa); }
    if instrument_type == Some("etf") { return Some(AssetClass::Etf); }
    match category?.to_ascii_lowercase().as_str() {
        "crypto" | "cryptocurrency" => Some(AssetClass::Crypto),
        "stablecoin" => Some(AssetClass::Stablecoin),
        "rwa" | "tokenized stock" => Some(AssetClass::Rwa),
        "stock" => Some(AssetClass::Stock),
        "etf" => Some(AssetClass::Etf),
        "fiat" | "currency" => Some(AssetClass::Fiat),
        _ => None,
    }
}

pub fn stablecoin(category: Option<&str>, external_id: &str) -> bool {
    classify(external_id, category, None) == Some(AssetClass::Stablecoin)
}

